```cpp
#include <iostream>
#include <fstream>
#include <vector>
#include <algorithm>
#include <iomanip>
#include <cmath>
using namespace std;

int main() {
    ifstream plik("wyniki.txt");
    vector<int> w;
    int x;
    while (plik >> x) w.push_back(x);
    int n = w.size();

    double suma = 0;
    for (int v : w) suma += v;
    double avg = suma / n;

    sort(w.begin(), w.end());
    int mediana = w[n / 2];

    cout << fixed << setprecision(2);
    cout << "a) Statystyki:" << endl;
    cout << "   Srednia: " << avg << endl;
    cout << "   Mediana: " << mediana << endl;
    cout << "   Min: " << w[0] << endl;
    cout << "   Max: " << w[n - 1] << endl;

    int powyzej = 0;
    for (int v : w) {
        if (v > avg) powyzej++;
    }
    cout << endl << "b) Powyzej sredniej: " << powyzej << " ("
         << fixed << setprecision(1) << (powyzej * 100.0 / n) << "%)" << endl;

    cout << endl << "c) Zakres: " << w[n - 1] - w[0] << endl;
    cout << fixed << setprecision(2);
    cout << "   Odleglosc mediany od sredniej: " << fabs(mediana - avg) << endl;
    return 0;
}
```

